UPDATE contents SET body = '١- أصبحنا على فِطْرَةِ الإسلامِ، وكَلِمَةِ الإخلاصِ، ودِينِ نَبِيِّنَا مُحمَّدٍ ﷺ، ومِلَّةِ أَبِينَا إبراهيمَ، حنيفًا مُسلِمًا، وما كَانَ مِنَ المُشْرِكِينَ', source = 'عن عبد الرحمن بن أبزي ﵁ قال: «كان رسول الله ﷺ يُعلِّمنا إذا أصبح أحدُنا أن يقول -فذكره-». [صحيح على شرط الشيخين]' WHERE id = 1;
UPDATE contents SET body = '٢- رَضِيتُ باللهِ رَبًّا، وبالإسلامِ دِينًـا، وبمُحمَّدٍ ﷺ نَبِيًّـا', source = 'عن المُنَيْذِرِ ﵁ قال: سمعتُ رسولَ الله ﷺ يقول: «من قال إذا أصبح -فذكره- فأنا الزعيم، لآخُذَنَّ بِيَدِهِ حتى أُدخِلَه الجنة». [صحيح]

حاشية: الزعيم: الضامن والكفيل.' WHERE id = 2;
UPDATE contents SET source = 'عن أبي هريرة ﵁ قال: «كان النبي ﷺ إذا أصبح قال: -فذكره-، وإذا أمسى قال: (اللهم بك أمسينا، وبك أصبحنا، وبك نحيا، وبك نموت، وإليك المصير)». [صحيح]' WHERE id = 3;
UPDATE contents SET source = 'عن أبي عياش ﵁ قال: قال رسول الله ﷺ: «من قال إذا أصبح -فذكره- كان عَدلَ عِتْقِ رقبةٍ من ولد إسماعيل عليه السلام، وكُتِبَ له عَشرُ حسناتٍ، وحُطَّ عنه عَشرُ سيئاتٍ، ورُفِعَ له عَشرُ درجاتٍ، وكان في حِرزٍ من الشيطان حتى يُمسي، فإن قالها إذا أمسى كان له مثلُ ذلك حتى يُصبح». [صحيح]' WHERE id = 4;
UPDATE contents SET source = 'عن أنس ﵁ قال: قال رسول الله ﷺ لفاطمة ﵂: «ما يمنعك أن تسمعي ما أُوصِيك به؟ أن تقولي إذا أصبحتِ وإذا أمسيتِ» -فذكره-. [حسن]' WHERE id = 5;
UPDATE contents SET source = '[البقرة: ٢٥٥]

عن أُبَيِّ بن كعب ﵁ أنه قال للجني: «فما يُنجينا منكم؟» قال: «هذه الآية التي في سورة البقرة: ﴿ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُ ﴾ [البقرة: ٢٥٥]، من قالها حين يُمسي أُجِيرَ منا حتى يُصبح، ومَن قالها حين يُصبح أُجِيرَ منا حتى يُمسي»، فلما أصبح أتى رسولَ الله ﷺ فذكر ذلك له، فقال: «صدق الخبيثُ». [صحيح]' WHERE id = 6;
UPDATE contents SET source = 'عن شداد بن أوس ﵁ عن النبي ﷺ قال: «سيدُ الاستغفار أن يقول العبد: -فذكره- من قالها مُوقنًا بها حين يُمسي، فمات من ليلته؛ دخل الجنة، ومن قالها موقنًا بها حين يُصبح، فمات من يومه؛ دخل الجنة». [البخاري]

حاشية: وتقول المرأة: «وأنا أَمَتُكَ» مكان: «وأنا عبدُكَ» في مثل هذا الموضع على الراجح، قال تعالى: ﴿ وَٱلصَّٰلِحِينَ مِنۡ عِبَادِكُمۡ وَإِمَآئِكُمۡۚ ﴾ الآية [النور: ٣٢]، فالعطف بالواو للمغايرة؛ لأن العبد خلافُ الأمة.' WHERE id = 7;
UPDATE contents SET source = 'عن عبد الله بن عمرو ﵄: أن أبا بكر ﵁ سأل النبي ﷺ قال: يا رسول الله علِّمْني ما أقول إذا أصبحتُ وإذا أمسيتُ، فقال: «يا أبا بكر! قُل:...» -فذكره-. [صحيح]

حاشية: وقوله: «وشِرْكِهِ» أي: ما يدعو إليه من الشرك بالله، وبفتح الشين والراء: ما يَصِيد به.' WHERE id = 8;
UPDATE contents SET source = 'عن عبد الله بن مسعود ﵁ قال: «كان نبيُّ الله ﷺ إذا أمسى قال: «أمسينا» -فذكره-، وإذا أصبح قال ذلك أيضًا: «أصبحنا...» -فذكره-». [مسلم]' WHERE id = 9;
UPDATE contents SET source = 'عن ابن عمر ﵄ قال: «لم يكن رسول الله ﷺ يَدَعُ هؤلاء الدعوات حين يُصبح، وحين يُمسي» -فذكره-. [صحيح]

حاشية: روعاتي: جمع روعة، وهي الفزعة.

حاشية: والاغتيال: الاحتيال، وحقيقته أن يُدْهَى الإنسان على غفلة منه من حيث لا يشعر، أي: أُخَذَ غِيلةً من تحتي، قال وكيع: «يعني الخسف».' WHERE id = 10;
UPDATE contents SET source = 'عن أم سلمة ﵂: «أن رسول الله ﷺ كان إذا أصبح قال...» فذكرَته. [حسن]' WHERE id = 11;
UPDATE contents SET source = 'عن أبي هريرة ﵁ قال رسول الله ﷺ: «إذا أصبح أحدُكم فليقل: -فذكره-، وإذا أمسى فليقل مثل ذلك». [حسن]' WHERE id = 12;
UPDATE contents SET source = 'عن عثمان ﵁ قال: سمعتُ رسول الله ﷺ يقول: «ما من عبدٍ يقول في صباح كل يوم، ومساء كل ليلة: -فذكره- فيضرَّه شيء». [صحيح]' WHERE id = 13;
UPDATE contents SET source = 'عن جويرية ﵂ أن النبي ﷺ خرج من عندها بُكرة حين صلى الصبح، وهي في مسجدها، ثم رجع بعد أن أضحى، وهي جالسة، فقال: «ما زِلتِ على الحال التي فارقتُكِ عليها؟»، قالت: نعم، قال النبي ﷺ: «لقد قلتُ بعدَكِ أربعَ كلمات، ثلاثَ مرّات، لو وُزِنت بما قلتِ منذ اليوم لَوَزَنَتْهُنَّ -فذكره-». [مسلم]' WHERE id = 14;
UPDATE contents SET source = 'عن عبد الرحمن بن أبي بكرة أنه قال لأبيه: يا أبتِ، إني أسمعك تدعو كل غداة -فذكره-، ثم قال: تُعيدها ثلاثًا حين تصبح، وثلاثًا حين تُمسي، فقال: «نعم، يا بُنيَّ، سمعتُ رسول الله ﷺ يقول بهن، وأنا أُحبُّ أن أستَنَّ بِسُنَّتِه». [حسن]' WHERE id = 16;
UPDATE contents SET source = 'عن عبد الله بن خُبيب ﵁ أن النبي ﷺ أمره أن يقرأ: ﴿ قُلۡ هُوَ ٱللَّهُ أَحَدٌ ﴾، والمعوذتين «حين تُمسي، وحين تُصبح، ثلاثَ مرّات، تكفيك من كل شيء». [حسن]' WHERE id = 17;
UPDATE contents SET source = '[التوبة: ١٢٩]

عن أبي الدرداء ﵁ قال: «من قال إذا أصبح، وإذا أمسى: ﴿ حَسۡبِيَ ٱللَّهُ... ﴾ الآية [التوبة: ١٢٩] سبعَ مرّات؛ كفاه الله ما أهمَّه». [موقوف صحيح، له حكم الرفع]' WHERE id = 18;
UPDATE contents SET source = 'عن أبي أيوب الأنصاري ﵁ أن رسول الله ﷺ قال: «من قال حين يصبح -فذكره- كُتِبَ الله له بكل واحدة قالها عشر حسنات، وحَطَّ الله عنه بها عشر سيئات، ورَفَعَه الله بها عشر درجات، وكُنَّ له كعشر رقاب، وكُنَّ له مَسْلَحةً من أول النهار إلى آخره، ولم يعمل يومئذ عملًا يقهرهنَّ، فإن قال حين يُمسي، فمثل ذلك». [صحيح]' WHERE id = 19;
UPDATE contents SET source = 'عن أبي هريرة ﵁ قال: قال رسول الله ﷺ: «من قال حين يُصبح، وحين يُمسي: (سبحان الله وبحمده) مئة مرّة؛ لم يأتِ أحدٌ يوم القيامة بأفضل مما جاء به، إلا أحدٌ قال مثل ما قال، أو زاد عليه». [مسلم] وفي رواية أبي داود: «من قال حين يُصبح: (سبحان الله العظيم وبحمده) مئة مرّة، وإذا أمسى كذلك؛ لم يُوافِ أحدٌ من الخلائق بمثل ما وافى». [صحيح]

حاشية: وافى: أتى، واستوفيت حقي: أخذتُه تامًّا.' WHERE id = 21;
UPDATE contents SET source = 'عن أبي موسى الأشعري ﵁ قال: جاء رسول الله ﷺ ونحن جلوس، فقال: «ما أصبحتُ غداةً قطُّ إلا استغفرتُ الله فيها مئةَ مرّة». [صحيح]

حاشية: ولم يوظَّف هنا صيغة معيَّنة للاستغفار، وأخصرها المذكور، وأفضلها المأثور، ولا سيَّما (سيد الاستغفار).

حاشية: وقد اقتبس الشوكاني ﵀ من قوله تعالى: ﴿ وَأَنِ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِ ﴾ [هود: ٣] صيغة: «اللهم إني أستغفرك فاغفر لي، وأتوب إليك فتب عليَّ» كما في «تحفة الذاكرين» (ص٤٠١).' WHERE id = 23;
UPDATE contents SET source = 'عن عمرو بن شعيب، عن أبيه، عن جده: قال رسول الله ﷺ: «من قال: (سبحان الله) مئة مرة قبل طلوع الشمس، وقبل غروبها، كان أفضل من مئة بَدَنة، ومن قال: (الحمد لله) مئة مرة قبل طلوع الشمس، وقبل غروبها، كان أفضل من مئة فرسٍ يُحمل عليها في سبيل الله، ومن قال: (الله أكبر) مئة مرة قبل طلوع الشمس، وقبل غروبها، كان أفضل من عِتق مئة رقبة، ومن قال: (لا إله إلا الله وحده، لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير) مئة مرة قبل طلوع الشمس، وقبل غروبها، لم يَجِئْ يوم القيامة أحدٌ بعمل أفضل من عمله إلا مَن قال مثل قوله، أو زاد عليه». [حسن]' WHERE id = 27;
UPDATE contents SET source = 'عن جُبَير بن مُطْعِم ﵁ مرفوعًا: «من قال: ...، فقالها في مجلس ذكر؛ كانت كالطابَع يُطبع عليه، ومن قالها في مجلس لغو؛ كانت كفارةً له». [صحيح على شرط مسلم]

وعن أم المؤمنين عائشة ﵂ أن رسول الله ﷺ كان إذا جلس مَجْلِسًا، أو صلّى صلاةً؛ تكلَّم بكلمات، فسألَتْه عائشةُ عن الكلمات، فقال: «إن تكلَّم بخير كان طابَعًا عليهنَّ إلى يوم القيامة، وإن تكلَّم بغير ذلك كان كفارةً له: (سبحانك اللهم وبحمدك، لا إله إلا أنت، أستغفرك وأتوب إليك)». [صحيح]

حاشية: وقوله: «كالطابع»: هو الخاتَم على الصحيفة، يريد أنه يُختَم عليها، وتُرفَع، كما يفعل الإنسانُ بما يَعِزُّ عليه. انظر: «النهاية» (٣/ ١١٢).
وقيل: طابَع عليه، أي: خاتَم عليه، إما على الحقيقة أو التشبيه، والمقصود: أن عمله محفوظ لا يضيع أبدًا.
وقال السندي: «المراد أنه يكون مُثبَّتًا لذلك الخير، رافعًا له إلى درجة القبول، آمنًا له عن حضيض الرَّد، وإن كان غير ذلك كان كفارة له»، انظر: «مرعاة المفاتيح» (٨/ ٢٠٤).' WHERE id = 28;
UPDATE contents SET source = 'عن أبي هريرة، قال: جاء رجلٌ إلى النبي ﷺ فقال: يا رسول الله، ما لقيتُ من عقربٍ لَدَغَتْنِي البارحةَ؟ قال: «أمَا لو قلتَ حين أمسيتَ -فذكره- لم تَضُرَّكَ». [مسلم] وفي رواية للترمذي وغيره: «ثلاثَ مرّاتٍ». [صحيح]' WHERE id = 40;
UPDATE contents SET source = '[الإخلاص]

حاشية: تواترت الأحاديث بكون ﴿ قُلۡ هُوَ ٱللَّهُ أَحَدٌ ﴾ تعدل ثلث القرآن:
منها: ما رواه أبو سعيد الخدري ﵁ أنه عن النبي ﷺ قال: «أيَعجِزُ أحدُكم أن يقرأ ثُلُثَ القرآنِ في ليلة؟» قال: فشقَّ ذلك على أصحابه، فقالوا: من يُطيقُ ذلك؟ قال: «يقرأ: ﴿ قُلۡ هُوَ ٱللَّهُ أَحَدٌ ﴾ فهي ثُلُثُ القرآن». [البخاري]
والمقصود أن قراءتها لها جزاءُ وثوابُ قراءة ثُلُث القرآن، لكنها لا تُجزئ عن قراءة ثلث القرآن الكريم.' WHERE id = 54;
UPDATE contents SET source = '[البقرة: ٢٨٥، ٢٨٦]

عن أبي مسعود البدري ﵁ قال: قال رسول الله ﷺ: «من قرأ بالآيتين من آخر سورة البقرة في ليلة كفتاه». [متفق عليه]

حاشية: «كفتاه»: أي أجزأتاه عن قيام الليل، وقيل: كفتاه من كل شيطان، فلا يقربه ليلته؛ وقيل: كفتاه ما يكون من الآفات التي تكون في تلك الليلة، وقيل: معناه حسبه بها فضلًا وأجرًا، ولا مانع من إرادة هذه الأمور جميعها، ويؤيده: أن حذف المتعلق مشعر بالتعميم، فكأنه قال: «كفتاه من كل شر، أو من كل ما يخاف، وفضل الله واسع» أفاده الشوكاني. انظر: «تحفة الذاكرين» (ص٩٩، ٢٣٥).
وروى مسلم أن مَلَكًا قال للنبي ﷺ: «أبشر بنورين أوتيتَهما، لم يؤتهما نبيٌّ قبلك: فاتحةِ الكتاب، وخواتيمِ سورة البقرة، لن تقرأ بحرفٍ منهما إلا أُعطيتَه».' WHERE id = 55;
UPDATE contents SET source = 'عن عبد الله بن مسعود ﵁ قال: «من قرأ: ﴿ تَبَٰرَكَ ٱلَّذِي بِيَدِهِ ٱلۡمُلۡكُ ﴾ كلَّ ليلة؛ منعه الله بها من عذاب القبر، وكنا في عهد رسول الله ﷺ نُسمِّيها (المانعة)، وإنها في كتاب الله سورة من قرأ بها في كل ليلة فقد أكثر وأطاب». [موقوف حسن]
وعنه ﵁ قال: «يُؤتى الرجل في قبره، فيُؤتى رجلاه، فيقولان: ليس لكم على ما قِبَلَنا من سبيل؛ كان يقرأ علينا سورة الملك، ثم يُؤتى جَوْفُه فيقول: ليس لكم عليَّ سبيل؛ قد وَعَى فيَّ سورة الملك، ثم يُؤتى من رأسه فيقول: ليس لكم على ما قِبَلي سبيل؛ كان يقرأ فيَّ سورة الملك». قال عبد الله: «فهي المانعة تمنع عذاب القبر، وهي في التوراة هذه سورة الملك من قرأها في ليلة أكثر وأطيب». [موقوف حسن]
ومثل هذا لا يُقال من قِبَل الرأي؛ فله حُكمُ المرفوع.' WHERE id = 56;
UPDATE contents SET source = 'التشهد في الصلاة. (ص106–107)

حاشية: أي: الألفاظ التي تدل على السلام والملك والبقاء وهي «لله» تعالى، و«الصلوات» أي: الأدعية التي يُرادُ بها تعظيم الله تعالى وهو مستحقُّها، لا تليقُ بأحدٍ سواه.

حاشية: أي: ما طاب من الكلام، وحَسُنَ أن يُثْنَى به على الله دون ما لا يليق بصفاته مما كان الملوك يُحَيَّوْنَ به.

حاشية: معناه التعويذ بالله والتحصين به، فإنَّ السلام اسم له سبحانه، وتقديره: الله عليك حفيظ وكفيل، كما يقال: «الله معك» أي بالحفظ والمعونة واللطف، وقد جاء في الرواية هكذا بصيغة الخطاب: «السلام عليك»، وانظر: «الشرح الممتع» للعلامة ابن عثيمين ﵀ (٣/ ١٥٠، ١٥١).

حاشية: هو اسم لكل خير فائض منه على الدوام.

حاشية: عن ابن مسعود ﵁ قال: «علَّمني رسول الله ﷺ التشهُّدَ وكَفِّي بين كَفَّيْهِ، كما يُعَلِّمُني السورةَ من القرآن:...» فذكره، ومع أنَّ سائرَ التشهدات صحيحة، لكنَّ تشهد ابن مسعود ﵁ أصحُّها؛ لأنه محفوظ الألفاظ رواه الشيخان، كما أنه لم يُخْتَلَفْ في حرفٍ منه، وسائر الصِّيَغ غالِبُها يوافق ألفاظَه، مما يقتضي أنه الذي كان يأمر به النبي ﷺ غالبًا، وانظر: «مجموع الفتاوى» (٢٢/ ٦٩).' WHERE id = 120;
UPDATE contents SET source = 'الصلاة على النبي ﷺ بعد التشهد. (ص109)

حاشية: الأقرب أنَّ الكاف هنا للتعليل، وأنَّ هذا من باب التوسُّل بفعل الله السابق، لتحقيق الفعل اللاحق، أي: كما أنه سبق الفضلُ منك -سبحانك- على آل إبراهيم، فأَلْحِقِ الفضلَ منك على محمدٍ وآلِه.
قال ابنُ مالكٍ ﵀:
شَبِّهْ بكافٍ وبها التعليلُ قَدْ
يُعنَى وزائدًا لِتَوْكيدٍ وَرَدْ
ومثال ذلك قوله تعالى: ﴿كَمَا أَرْسَلْنَا فِيكُمْ رَسُولًا مِنْكُمْ يَتْلُو عَلَيْكُمْ آيَاتِنَا﴾ الآية [البقرة: ١٥١]، وكذلك الكاف في قوله ﷿: ﴿وَاذْكُرُوهُ كَمَا هَدَاكُمْ﴾ [البقرة: ١٩٨] أي: لهدايتكم، وانظر: «الشرح الممتع» (٣/ ١٦٥، ١٦٦).

حاشية: من البركة وهي النماء والزيادة، والتبريك الدعاء بذلك، فهذا الدعاء يتضمن إعطاءه ﷺ ما أعطاه لآل إبراهيم وإدامته وثبوته له، ومضاعفته له، وزيادته.' WHERE id = 121;
UPDATE contents SET source = 'الصلاة على النبي ﷺ بعد التشهد. (ص111)' WHERE id = 122;
UPDATE contents SET source = 'الدعاء بعد التشهُّد الأخير. (ص112)

حاشية: هو الأمر الذي يأثَمُ به الإنسانُ، أو هو الإثمُ نفسُه وضعًا للمصدر موضعَ الاسم، وأمَّا (المغرم) فيريدُ به الدَّيْنَ، بدليل تمام الحديث: قالت عائشة: فقال له قائل: ما أكثرَ ما تستعيذُ من المغرم يا رسول الله! فقال ﷺ: «إن الرجل إذا غَرِمَ حَدَّثَ فكَذَبَ، ووعد فأخلف».' WHERE id = 124;
UPDATE contents SET body = '٩- اللهم إنِّي أسألُكَ من الخيرِ كُلِّه، عاجِلِهِ وآجِلِه، ما عَلِمْتُ منه وما لم أعلمْ، وأعوذُ بك من الشَّرِّ كُلِّه، عاجِلِهِ وآجِلِه، ما عَلِمْتُ منه وما لَمْ أعلمْ، اللهم إنِّي أسألُكَ الجَنَّةَ، وما قَرَّبَ إليها مِنْ قَوْلٍ أو عَمَلٍ، وأعوذُ بكَ من النَّارِ، وما قَرَّبَ إليها من قولٍ أو عملٍ، اللهم إنِّي أسألُكَ من خيرِ ما سألَكَ عبدُكَ ورسولُكَ محمدٌ ﷺ، وأعوذُ بِكَ من شَرِّ ما استعاذَكَ منه عبدُكَ ورسولُكَ محمدٌ ﷺ، وأسألُكَ ما قَضَيْتَ لي مِنْ أمرٍ أن تجعلَ عاقِبَتَهُ لي رَشَدًا' WHERE id = 131;
UPDATE contents SET source = 'قنوت الوتر في رمضان وغيره. (ص104–105)

حاشية: قال النووي ﵀: «واعلم أنَّ المنقول عن عمر ﵁: (عَذِّبْ كَفَرَةَ أهلِ الكتابِ)؛ لأنَّ قتالَهم ذلك الزمانَ كانَ مع كَفَرَةِ أهلِ الكتابِ، وأمَّا اليومَ فالاختيارُ أنْ يقولَ: (عَذِّبِ الكَفَرَةَ)؛ فإنَّه أعمُّ». اهـ. من «الأذكار» (ص٥٨).' WHERE id = 154;
UPDATE contents SET source = 'قنوت الوتر في رمضان وغيره. (ص105)

حاشية: لكنه يدعو عند كل نازلة بما يناسبها، وأما قنوت الحسن بن علي ﵄ فهو واردٌ في قنوت الوتر، ولم يثبت الدعاء به في النوازل، والله أعلم.' WHERE id = 156;
UPDATE contents SET source = 'ما يقول إذا أراد النوم. [موقوفٌ على عائشة ﵂]. (ص134)' WHERE id = 174;
UPDATE contents SET source = 'ما يُقال عند المريض، ويُقْرَأ عليه. (ص160)

حاشية: من آدابِ الدعاء أن تتوسَّلَ إلى الله ﷿ فيما إذا أجاب دعوتك، أنك ستستعين بها على الاستزادة من الطاعات والقربات كما في هذا الحديث، وكما قال موسى عليه السلام: ﴿ وَٱجۡعَل لِّي وَزِيرٗا مِّنۡ أَهۡلِي ٢٩ هَٰرُونَ أَخِي ٣٠ ٱشۡدُدۡ بِهِۦٓ أَزۡرِي ٣١ وَأَشۡرِكۡهُ فِيٓ أَمۡرِي ٣٢ كَيۡ نُسَبِّحَكَ كَثِيرٗا ٣٣ وَنَذۡكُرَكَ كَثِيرًا ٣٤ إِنَّكَ كُنتَ بِنَا بَصِيرٗا ﴾ [طه: ٢٩-٣٥].' WHERE id = 263;
UPDATE contents SET source = 'رقية المريض. (ص161)

حاشية: قال الحافظ ﵀: «قوله: (تربة أرضنا) خبر مبتدأٍ محذوفٍ، أي: هذه تربة أرضنا، وقوله: «بريقة بعضنا» يدل على أنه يتفل عند الرقية، قال النووي: معنى الحديث أنه أخذ من ريق نفسه على إصبعه السبابة، ثم وضعها على التراب، فعلق به شيء منه، ثم مسح به الموضعَ العليل أو الجريح قائلًا الكلامَ المذكورَ في حالة المسح».اهـ. من «فتح الباري» (١٠/ ٢٠٨).
وعن عائشةَ ﵂ أنَّ رسولَ الله ﷺ كان إذا اشتكى الإنسانُ الشيءَ منه، أو كانت به قَرْحَةٌ أو جُرْحٌ قال النبي ﷺ بإصبعه هكذا، ووضع سفيانُ سبابته بالأرض، ثم رفعها، وقال: «باسمِ الله، تربةُ أرضنا» الحديثَ، مُتَّفقٌ عليه.' WHERE id = 267;
UPDATE contents SET source = 'ما يقول إذا استشعر حُضُورَ أَجَلِه. (ص165)

حاشية: الرفيق الأعلى: هم الأنبياء والصِّدِّيقون والشهداء والصالحون المذكورون في قوله تعالى: ﴿ وَحَسُنَ أُوْلَٰٓئِكَ رَفِيقٗا ﴾ [النساء: ٦٩]، وقيل: هم الملائكة المقرَّبون، وقيل: الجنة، وقيل: هو دعاء بأن يلحق بالله ﷿، كما يقال: «الله رفيقٌ بعباده» من الرِّفق والرأفة.' WHERE id = 275;
UPDATE contents SET body = '٢- ويَحْمَدُ اللهَ ﷿' WHERE id = 276;
UPDATE contents SET source = 'ما يقول إذا رأى الهلال. (ص175)

حاشية: الغَسَق: الظلمة، والوُقوب: الدخول في الظُّلمة ونحوها، فلعلَّ سببَ الاستعاذة منه في حال وقوبه أنَّ أهلَ الفساد ينتشرون في الظلمة، ويتمكنون فيها أكثر مما يتمكنون منه في حال الضياء، فيُقْدِمون على العظائم وانتهاكِ المحارم، فأضاف فعلهم في ذلك الحال إلى القمر؛ لأنهم يتمكنون منه بسببه، وهو من باب تسمية الشيء باسم ما هو من سببه، أو ملازم له. أفاده الحافظ أبو بكر الخطيب ﵀.' WHERE id = 294;
UPDATE contents SET source = 'أذكار المسافر. [الزخرف: ١٣، ١٤]. (ص179)

حاشية: مقرنين: أي مطيقين مقتدرين عليه، يعني: ما كنا نطيق قهره واستعماله لولا تسخير الله تعالى إيّاه لنا.

حاشية: وقد ضحِكَ رسولُ الله ﷺ بعدما قال هذا الدعاء، وذلك فيما رواه أمير المؤمنين علي بن أبي طالب ﵁ أنَّ النبي ﷺ فعل ذلك، وأنه ﵁ قال للنبي ﷺ: «يا رسول الله، مِنْ أيِّ شيءٍ ضحكتَ؟» فقال: «إنَّ رَبَّكَ سبحانه يعجب من عبده إذا قال: (اغفر لي ذنوبي)، يعلم أنه لا يغفر الذنوب غيري».' WHERE id = 306;
UPDATE contents SET source = 'أذكار المسافر. (ص182)

حاشية: أي: شهد شاهد، وحقيقته: ليسمع السامع، وليشهد الشاهد على حمد الله ﷾ على نعمه، وحُسن بلائه، وقيل معناه: انتشر ذلك وظهر، وسمعه السامعون.

حاشية: حسن البلاء: النعمة، والبلاء الاختبار والامتحان، فالاختبار بالخير ليتبين به الشكر، والابتلاء بالشر ليظهر الصبر.

حاشية: ربنا صاحبنا: أي: احفظنا، ومن صحبه الله لم يضرَّه شيء.

حاشية: عائذًا بالله من النار: يحتمل وجهين: أحدهما: أن يريد أنا عائذ بالله من النار، والآخر: أن يريد: متعوذ بالله، كما يقال: مستجار بالله، فوضع الفاعل مكان المفعول، كقولهم: ماء دافق، أي: مدفوق.' WHERE id = 314;
UPDATE contents SET source = 'ما يقول إذا زار البقيع وشهداء أحد. (ص206)

