UPDATE contents SET source = 'فضائل ذكر الله ﷿. (ص15)' WHERE id = 1676;
UPDATE contents SET body = 'كقوله تعالى: ﴿ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ ٱللَّهَ ذِكۡرٗا كَثِيرٗا ٤١ وَسَبِّحُوهُ بُكۡرَةٗ وَأَصِيلًا ﴾ [الأحزاب: ٤١، ٤٢]، وقوله ﷿: ﴿ فَٱذۡكُرُونِيٓ أَذۡكُرۡكُمۡ ﴾ [البقرة: ١٥٢]، وقوله جَلَّ وَعَلَا: ﴿ وَٱذۡكُر رَّبَّكَ فِي نَفۡسِكَ تَضَرُّعٗا وَخِيفَةٗ وَدُونَ ٱلۡجَهۡرِ مِنَ ٱلۡقَوۡلِ بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ وَلَا تَكُن مِّنَ ٱلۡغَٰفِلِينَ ﴾ [الأعراف: ٢٠٥].', source = 'فضائل ذكر الله ﷿. (ص15)' WHERE id = 1677;
UPDATE contents SET body = 'عن أبي هريرة ﵁: قال رسولُ الله ﷺ: «يقول اللهُ ﷿: أنا مع عبدي ما ذَكَرني، وتحرَّكَتْ بي شفتاه».', source = 'فضائل ذكر الله ﷿. (ص15)' WHERE id = 1678;
UPDATE contents SET body = 'وعن أبي الدرداء ﵁ أنَّ رسول الله ﷺ قال: «ألا أخبركم بخيرِ أعمالِكم، وأرفعِها في درجاتِكم، وأزكاها عند مَليكِكم، وخيرٍ لكم من إعطاء الوَرِق والذهب، وخيرٍ لكم من أن تَلقَوْا أعداءَكم فتضربوا أعناقَهم، ويضربوا أعناقَكم؟»، قالوا: بلى، قال: «ذكرُ الله».', source = 'فضائل ذكر الله ﷿. (ص16)' WHERE id = 1679;
UPDATE contents SET body = 'وقال عبدُ الله بن بُسْرٍ ﵁: يا رسولَ الله، أيُّ الأعمال أفضل؟ قال: «أن تفارقَ الدنيا ولسانُكَ رَطبٌ من ذكر الله».', source = 'فضائل ذكر الله ﷿. (ص16)' WHERE id = 1680;
UPDATE contents SET body = 'وعن أبي هريرة ﵁ قال: سمعتُ رسولَ الله ﷺ يقول: «ثلاثةٌ لا يُرَدُّ دعاؤهم: الذاكر اللهَ كثيرًا، ودعوة المظلوم، والإمام المُقسِط».', source = 'فضائل ذكر الله ﷿. (ص16)' WHERE id = 1681;
UPDATE contents SET body = 'ورُوِيَ عن معاذِ بْنِ جبلٍ ﵁ مرفوعًا: «ما عَمِلَ آدمِيٌّ قطُّ عملًا أنْجَى له مِن عذابِ اللهِ؛ مِنْ ذِكْرِ اللهِ تعالى».', source = 'فضائل ذكر الله ﷿. (ص16)' WHERE id = 1682;
UPDATE contents SET body = 'قال النووي ﵀: «اعلم أنَّ الأذكار المشروعة في الصلاةِ وغيرها، واجبةً كانت أو مستحبة، لا يُحسَبُ شيءٌ منها، ولا يُعتَدُّ به حتى يَتَلَفَّظَ به، بحيث يُسمِعُ نفسَه، إذا كان صحيحَ السمع لا عارضَ له».اهـ.' WHERE id = 1684;
UPDATE contents SET body = 'عن سَمُرةَ بنِ جُنْدُبٍ ﵁ عن النبيِّ ﷺ قال: «إذا حَدَّثتُكُم حديثًا؛ فلا تَزِيدُنَّ عَلَيَّ» الحديث، ومعناه يشملُ النهي عن الزيادة في لفظ الذكر تعبُّدًا.' WHERE id = 1688;
UPDATE contents SET body = 'وأنكر ابنُ عمرَ ﵄ على مَن زاد الصلاةَ على النبي ﷺ بعد الحمد عَقِبَ العُطاس، بحجة أنه مخالف لتعليمه ﷺ، وقال له: «وأنا أقول: الحمد لله، والسلام على رسول الله ﷺ، ولكن ليس هكذا علَّمنا رسولُ الله ﷺ، علَّمنا إذا عَطَسَ أحدُنا أن يقولَ: الحمد لله على كلِّ حال».' WHERE id = 1689;
UPDATE contents SET body = 'وعلَّمَ النبيُّ ﷺ البراءَ بنَ عازبٍ ﵁ دعاءً يقوله عند النوم، وفي آخره: «اللهم آمنتُ بكتابك الذي أنزلتَ، وبنبيك الذي أرسلتَ»، يقول البراء: فَرَدَّدْتُها على النبيِّ ﷺ، فلمَّا بلغتُ: «اللهم آمنتُ بكتابك الذي أنزلت»، قلتُ: ورسولِك، قال: «ونبيك الذي أرسلت»، فهذا يدلُّ على عدمِ جواز تبديل ألفاظ الأذكار المأثورة؛ لأنها توقيفية، ولها خصائص وأسرار لا يدخلها القياس.' WHERE id = 1690;
UPDATE contents SET body = 'قال النووي ﵀: «...واختار المازَري أنَّ سبب الإنكار أنَّ هذا ذكرٌ ودعاء، فينبغي فيه الاقتصار على اللفظ بحروفه».' WHERE id = 1691;
UPDATE contents SET body = 'ففي حديث الاستخارة: «كان رسول الله ﷺ يعلمنا الاستخارةَ في الأمور كلِّها كما يعلمنا السورةَ من القرآن»، وقال ابنُ مسعودٍ ﵁: «عَلَّمَني رسُولُ الله ﷺ التشهُّدَ، وكَفِّي بين كَفَّيْهِ، كما يُعَلِّمُني السورةَ من القرآن».' WHERE id = 1693;
UPDATE contents SET body = 'وفي حديث ابن عبَّاسٍ ﵄، أنَّ رسولَ اللهِ ﷺ كان يعلمهم هذا الدعاء كما يعلمهم السورةَ من القرآن، يقول: «اللهم إني أعوذ بك من عذاب جهنم...» الحديث.' WHERE id = 1694;
UPDATE contents SET body = 'وقد طلب بعضُ الصحابةِ ﵃ من رسول الله ﷺ -أفصحِ مَنْ نَطَقَ بالضَّاد، الذي أُوتِيَ جوامعَ الكَلِم- أن يُعَلِّمَهم ما يدعون به من الصِّيَغ، ولم يَدْعُوا من تلقاء أنفسهم، مع أنهم كانوا الغايةَ في الفصاحة والبلاغة؛ لأنهم عِلِموا أنَّ الدعاء عبادةٌ تحتاجُ توقيفًا من النبي ﷺ.', source = 'الأدعية الراتبة توقيفية لا يزاد فيها، ولا ينقص منها. (ص22–23)

حاشية: فقد قال الصديق ﵁ لرسول الله ﷺ: «عَلِّمني دعاءً أدعو به في صلاتي»، فقال: «قل: اللهم إني ظلمتُ نفسي ظلمًا كثيرًا...» الحديث.
وقال له أيضًا: يا رسول الله، علِّمْني ما أقولُ إذا أصبحتُ، وإذا أمسيتُ، فقال: «يا أبا بكر، قُل: اللهم فاطرَ السماوات والأرض...» الحديث.' WHERE id = 1696;
UPDATE contents SET body = 'قال الإمام أبو بكر محمد بن الوليد الطُّرْطوشي (ت ٥٢٠هـ) ﵀: «ومن العجب العُجاب أن تُعْرِضَ عن الدعوات التي ذكرها الله في كتابه عن الأنبياء، والأولياء، والأصفياء، مقرونةً بالإجابة، ثم تنتقيَ ألفاظَ الشعراء والكُتَّاب كأنَّك قد دعوتَ في زعمِك بجميع دعواتهم، ثم استعنتَ بدعواتِ مَنْ سواهم».اهـ.' WHERE id = 1698;
UPDATE contents SET body = 'وقال ذَهَبِيُّ العصرِ العلَّامةُ المجدد عبدُ الرحمن بن يحيى المُعَلِّمي اليماني (ت ١٣٨٦هـ) ﵀: «وما أخسرَ صفقةَ مَن يَدَعُ الأدعيةَ الثابتة في كتابِ الله ﷿ أو في سُنَّةِ رسوله ﷺ فلا يكادُ يدعو بها! ثم يعمَدُ إلى غيرها فيتحرَّاه ويواظب عليه، أليس هذا من الظلم والعدوان؟!».' WHERE id = 1699;
UPDATE contents SET body = 'وعن أنسِ بنِ مالكٍ ﵁ قال: قال رسولُ الله ﷺ: «قال اللهُ تبارك وتعالى: يا بْنَ آدمَ إنَّكَ ما دعوتَني ورجَوتَني غفَرتُ لَكَ على ما كانَ فيكَ ولا أُبالي، يا بْنَ آدمَ لو بلغَتْ ذنوبُكَ عَنانَ السَّماءِ، ثمَّ استغفرتَني غفرتُ لَكَ ولا أبالي، يا بْنَ آدمَ إنَّكَ لو أتيتَني بقُرابِ الأرضِ خطايا ثمَّ لقيتَني لا تشرِكُ بي شيئًا؛ لأتيتُكَ بقُرابِها مغفرةً».' WHERE id = 1707;
UPDATE contents SET body = 'وعن عُقبةَ بنِ عامرٍ الجُهَنيِّ ﵁، أنَّ رجُلًا أتى رسولَ الله ﷺ، فقال: يا رسولَ اللهِ، أَحَدُنا يُذْنِبُ، قالَ: «يُكْتَبُ عليه». قالَ: ثُمَّ يَسْتَغْفِرُ مِنهُ ويَتوبُ، قالَ: «يُغْفَرُ له، ويُتابُ عليه». قالَ: فيَعودُ ويُذْنِبُ، قالَ: «يُكْتَبُ عليه»، قالَ: ثُمَّ يَسْتَغْفِرُ مِنهُ ويَتوبُ، قالَ: «يُغْفَرُ له، ويُتابُ عليه»، قالَ: فَيَعودُ وَيُذْنِبُ، قالَ: «يُكْتَبُ عليه»، قالَ: ثُمَّ يَسْتَغْفِرُ مِنهُ ويَتوبُ، قالَ: «يُغْفَرُ له، ويُتابُ عليه، ولا يَمَلُّ اللهُ حتَّى تَمَلُّوا».' WHERE id = 1708;
UPDATE contents SET body = 'وعن جابرٍ ﵁، قال رسول الله ﷺ: «مرَّ رجلٌ ممَّن كان قبلَكم بجُمْجُمةٍ، فنظر إليها، فحدَّث نفسَه بشيءٍ ثمَّ قال: يا ربِّ! أنتَ أنتَ، وأنا أنا، أنت العوَّادُ بالمغفرةِ، وأنا العوَّادُ بالذُّنوبِ! وخرَّ للهِ ساجدًا، فقيل له: ارفَعْ رأسَك، فأنت العوَّادُ بالذُّنوبِ، وأنا العوَّادُ بالمغفرةِ، فرفع رأسَه، فغُفِر له».' WHERE id = 1709;
UPDATE contents SET body = 'وعن أبي هريرةَ ﵁ أنَّ رسولَ الله ﷺ قال: «إنَّ العبدَ إذا أخطأ خطيئةً، نُكِتَت في قلبِه نُكتةٌ سوداءُ، فإن هو نزَعَ واستَغفَرَ وتاب صُقِل قلبُه، وإن عاد زِيدَ فيها حتى تعلوَ على قلبِه، وهو الرَّانُ الذي ذكَر اللهُ تعالى: ﴿كَلَّاۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكۡسِبُونَ﴾ [المطففين: ١٤]».' WHERE id = 1710;
UPDATE contents SET body = 'وعن فَضالةَ بنِ عُبَيدٍ ﵁، عنِ النبي ﷺ أنه قال: «العبدُ آمِنٌ مِن عَذابِ الله ما استغفَرَ اللهَ».' WHERE id = 1711;
UPDATE contents SET body = 'وعن أُمِّ المؤمنين عائشةَ ﵂، قالت: قيل: يا رسولَ الله، ماتت فلانةُ واستراحت! فَغَضِبَ رسولُ الله ﷺ، وقال: «إنَّما يستريحُ مَن غُفِرَ له».' WHERE id = 1712;
UPDATE contents SET body = 'وعن الزُّبيرِ بنِ العوَّامِ ﵁، قال: قال رسول الله ﷺ: «مَنْ أَحَبَّ أنْ تَسُرَّهُ صحيفتُهُ فَلْيُكْثِرْ فيها مِنَ الاستغفارِ».' WHERE id = 1713;
UPDATE contents SET body = 'ورُوِيَ عَنْ عَبْدِ الله بنِ عَبَّاسٍ ﵄ أنَّ رسولَ الله ﷺ قال: «مَن لَزِمَ الاستِغفارَ، جَعَلَ اللهُ له مِن كُلِّ ضِيقٍ مَخرَجًا، ومِن كُلِّ هَمٍّ فَرَجًا، ورَزَقَه مِن حيث لا يَحتَسِبُ».' WHERE id = 1714;
UPDATE contents SET body = 'وعنِ ابْنِ مَسْعودٍ ﵁ قال: «كان رسولُ الله ﷺ يُعْجِبُه أن يدعوَ ثلاثًا، ويستغفر ثلاثًا».' WHERE id = 1715;
UPDATE contents SET body = 'وعنه ﵁، قال رسول الله ﷺ: «مَنْ قالَ: (أَستَغفِرُ اللهَ الَّذي لا إلَهَ إلَّا هو، الحَيُّ القَيُّومُ وأَتوبُ إليه) ثلاثًا؛ غُفِرَتْ ذُنوبُه، وإنْ كان فارًّا مِنَ الزَّحْفِ».' WHERE id = 1716;
UPDATE contents SET body = '١٢- ومن أسباب مغفرة الذنوب: كثرة الصلاة على رسول الله ﷺ؛ لأنَّ أُبَيَّ بنَ كعبٍ ﵁ لَمَّا قال للنبي ﷺ: «أجعلُ لكَ صلاتي كلَّها؟» قال له النبيُّ ﷺ: «إذَن تُكفَى همَّكَ، وَيُغْفَرُ لك ذنبُك».' WHERE id = 1749;
UPDATE contents SET body = 'الباقيات الصالحات -التي وَرَدَ ذِكرُها في قوله تبارك وتعالى: ﴿ٱلۡمَالُ وَٱلۡبَنُونَ زِينَةُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَٱلۡبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيۡرٌ عِندَ رَبِّكَ ثَوَابٗا وَخَيۡرٌ أَمَلٗا﴾ [الكهف: ٤٦]، وفي قوله ﷿: ﴿وَيَزِيدُ ٱللَّهُ ٱلَّذِينَ ٱهۡتَدَوۡاْ هُدٗىۗ وَٱلۡبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيۡرٌ عِندَ رَبِّكَ ثَوَابٗا وَخَيۡرٞ مَّرَدًّا﴾ [مريم: ٧٦]- هي جميع أعمال الخير، كما جاء عن ابن عبَّاسٍ ﵄ في قوله: ﴿وَٱلۡبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ﴾، قال: «هي ذِكْرُ الله؛ قولُ: لا إله إلا الله، والله أكبرُ، وسبحانَ الله، والحمدُ لله، وتباركَ الله، ولا حول ولا قوَّةَ إلا بالله، وأستغفِرُ الله، وصلَّى اللهُ على رسولِ الله، والصيامُ، والصلاةُ، والحجُّ، والصدقةُ، والعِتْقُ، والجهادُ، والصلةُ، وجميعُ أعمالِ الحسناتِ، وهُنَّ الباقياتُ الصالحاتُ، التي تبقى لأهلها في الجنة ما دامتِ السماواتُ والأرض».' WHERE id = 1751;
UPDATE contents SET body = 'وعنه ﵁ أنَّ رسولَ الله ﷺ قال: «سبحانَ اللهِ، والحمدُ لله، ولا إله إلا الله، والله أكبرُ، من الباقيات الصالحات».' WHERE id = 1754;
UPDATE contents SET body = 'وعن سَمُرةَ بنِ جُنْدُبٍ ﵁ قال: قال رسولُ الله ﷺ: «أربعٌ هُنَّ مِن أطيَبِ الكلامِ، وهُنَّ من القرآنِ، ولا يضرك بأَيِّهِنَّ بدأتَ: سبحانَ الله، والحمدُ لله، ولا إله إلَّا الله، والله أكبر» الحديث.' WHERE id = 1755;
UPDATE contents SET body = 'وعن أنسٍ ﵁ أنَّ رسولَ الله ﷺ مَرَّ بشجرةٍ يابسةِ الورق، فضربها بعصاه، فتناثر الورق، فقال: «إنَّ الحمدَ لله، وسبحانَ الله، ولا إله إلا الله، والله أكبر، لَتُسَاقِطُ من ذنوبِ العبدِ كما تَسَاقَطَ ورقُ هذه الشجرةِ».' WHERE id = 1757;
UPDATE contents SET body = 'وعن عبد الله بن مسعودٍ ﵁ قال: قال رسول الله ﷺ: «إنَّ اللهَ قسم بينكم أخلاقَكم كما قسم بينكم أرزاقَكم، وإنَّ اللهَ يُعطي الدُّنيا من يُحِبُّ ومن لا يُحبُّ، ولا يُعطي الإيمانَ إلَّا من أحبَّ، فمن ضنَّ بالمالِ أن يُنفِقَه، وخاف العدوَّ أن يُجاهِدَه، وهاب اللَّيلَ أن يُكابِدَه، فليُكثِر من قولِ: سبحانَ اللهِ، والحمدُ للهِ، ولا إلهَ إلَّا اللهُ، واللهُ أكبرُ».' WHERE id = 1758;
UPDATE contents SET body = 'وعنه ﵁ أنَّ رسولَ الله ﷺ قال: «لَقِيتُ إبراهيمَ ليلةَ أُسرِيَ بي، فقال: يا محمدُ، أقرئْ أُمَّتَك مني السلامَ، وأَخْبِرْهُمْ أنَّ الجنةَ طيبةُ التربةِ، عذبةُ الماءِ، وأنها قِيعانٌ، وأنَّ غِراسَها سبحانَ اللهِ، والحمدُ للهِ، ولا إلهَ إلا اللهُ، واللهُ أكبرُ».' WHERE id = 1759;
UPDATE contents SET body = 'قال العلَّامةُ الصنعاني ﵀: «والأحاديثُ في فضلِ هذه الكلماتِ مجموعة ومتفرِّقة بحرٌ لا تُنْزِفه الدِّلاءُ، ولا يُنْقِصُه الإملاءُ».' WHERE id = 1760;
UPDATE contents SET body = 'ومما يدل على فضل التسبيح وجلالةِ قدرِه عند الله ﷿ أن التسبيح بتصاريفه المختلفة قد جاء في كتاب الله المجيد سبعًا وثمانين مرة.' WHERE id = 1765;
UPDATE contents SET body = 'والدليل على أن التسبيحَ تعظيمٌ ومدحٌ وثناءٌ لله تعالى قولُ رسولِ الله ﷺ: «فأما الركوع فعظِّموا فيه الربَّ ﷿»، وذلك يكون بالتسبيح مثل: «سبحان ربي العظيم»، و«سبحان ربي العظيم وبحمده» و«سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي»، ولما سُئل أمير المؤمنين علي ﵁ عن «سبحان الله»؛ قال: «تعظيمُ جَلالِ الله».' WHERE id = 1767;
UPDATE contents SET body = 'وقال أيضًا ﵁: «سبحان الله: كلمة أحبها الله لنفسه، ورَضِيَها، وأحبَّ أن تُقال».' WHERE id = 1768;
UPDATE contents SET body = 'وقال عُبَيْدُ بْنُ عُمَيْر ﵀: «تسبيحةٌ بحَمْدِ الله في صحيفة المؤمن خيرٌ من أن تسير أو تسيل مَعَهُ جبالُ الدُّنْيا ذهبًا».' WHERE id = 1773;
UPDATE contents SET source = 'أولًا: من صيغ التسبيح المفردة. [جزء من الآية (١٠٨) سورة يوسف]. (ص318)

حاشية: عن سعد بن أبي وقَّاص ﵁: كُنَّا عند رسولِ الله ﷺ، فقال: «أيعجز أحدكم أن يكسب كل يوم ألفَ حسنةٍ؟»، فسأله سائل من جلسائه: كيف يكسب أحدنا ألفَ حسنة؟ قال: «يسبح مِئَةَ تسبيحةٍ، فيُكتَبُ له ألفُ حسنةٍ، أو يُحَط عنه ألفُ خطيئةٍ».' WHERE id = 1776;
UPDATE contents SET source = 'أولًا: من صيغ التسبيح المفردة. (ص318)

حاشية: رُوِيَ عن أبي هريرة ﵁ قال: قال رسول الله ﷺ: «إنَّ الله جَلَّ ذِكْرَه أذِنَ لي أن أحدِّثَ عن ديكٍ قد مَرَقَتْ رجلاهُ الأرضَ، وعنقُهُ منثنٍ تحتَ العرشِ، وهوَ يقولُ: (سبحانَكَ ما أعظمَكَ ربَّنا!)، فيَرُدُّ عليه: (ما يعلمُ ذلكَ مَن حلفَ بي كاذبًا)». مرقت: اخترقت.' WHERE id = 1781;
UPDATE contents SET body = 'أكثر ما جاء التسبيح؛ مقرونًا بالحمد كقوله تعالى: ﴿وَسَبِّحۡ بِحَمۡدِ رَبِّكَ﴾ [طه: ١٣٠]، وقوله سبحانه: ﴿وَٱلۡمَلَٰٓئِكَةُ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ﴾ [الشورى: ٥]، وكذا وردت أحاديث كثيرة عن رسولِ الله ﷺ قَرَنَ فيها التسبيح بالحمد، مثل قوله ﷺ في حديث أبي مالك الأشعري ﵁: «سبحان الله، والحمدُ لله تملآنِ -أو- تملأُ ما بين السماوات والأرض».' WHERE id = 1785;
UPDATE contents SET body = 'وهذا كقوله ﷿:' WHERE id = 1786;
UPDATE contents SET source = 'اقتران التسبيح بالحمد. (ص320)

حاشية: عن أبي ذَرٍّ ﵁ أنَّ النبي ﷺ قال: «إنَّ أحبَّ الكلامِ إلى الله: سبحان الله وبحمده».
وعنه ﵁ أنَّ رسولَ الله ﷺ سُئلَ: أيُّ الكلامِ أفضلُ؟ فقال: «ما اصطفى الله لملائكته، أو لعباده: سبحان الله وبحمده».
وعن عبد الله بن خبيب ﵁ أنَّ رسولَ الله ﷺ قال: «مَنْ ضَنَّ بالمالِ أن ينفقه، وبالليل أن يُكابِدَه، فعليه بسبحان الله وبحمده».
وعن أبي هريرةَ ﵁ أنَّ رسولَ الله ﷺ قال: «مَن قال: سُبْحانَ اللهِ وبِحَمْدِه، في يومٍ مِئَةَ مَرَّةٍ؛ حُطَّتْ عنه خَطاياهُ وإنْ كانَتْ مِثْلَ زَبَدِ البَحْرِ».
وعن جابرٍ ﵁، قال رسول الله ﷺ: «مَنْ قال: سُبْحانَ اللهِ العظيمِ وبِحَمْدِه، غُرِسَتْ لهُ بها نخلةٌ في الجنةِ».' WHERE id = 1788;
UPDATE contents SET source = 'اقتران التسبيح بالحمد. (ص320)

حاشية: عن أبي هريرةَ ﵁، عن النبي ﷺ قال: «كلمتان خفيفتان على اللسان، ثقيلتان في الميزان، حبيبتان إلى الرحمن: سبحانَ اللهِ وبحمدِه، سبحان الله العظيم».
ولِعِظَمِ شأنِ هذا الحديث ختم به الإمامُ البخاريُّ ﵀ «جامعَه الصحيح».
تنبيه: الباء في «وبحمدك» للمصاحبة، بمعنى (مع)، أي: أجمعُ بين التسبيح والتحميد لفظًا، بأن أقولَ: «سبحانَ الله، والحمد لله»، وأجمع بينهما معنًى، بتنزيه الله عن النقائص، وإثبات ما يليق من المحامد وصفات الكمال.' WHERE id = 1789;
UPDATE contents SET body = 'وعن أبي موسى الأشعري ﵁ أنَّ رسول الله ﷺ قال: «إذا مات ولدُ الرَّجُلِ يقولُ الله تعالى لملائكته: أقبضتُم وَلَدَ عبدي؟ فيقولون: نعم. فيقول: أَقَبَضْتُم ثَمَرَةَ فُؤادِه؟ فيقولون: نعم. فيقول: فماذا قال عبدي؟ فيقولون: حَمِدَك واسترجع. فيقول: ابنُوا لعبدي بيتًا في الجنَّةِ، وسَمُّوه بيتَ الحمدِ».' WHERE id = 1820;
UPDATE contents SET body = 'وعن أنس ﵁ قال رسول الله ﷺ: «ما أنعم الله على عبدٍ بنعمةٍ فقال: (الحمد لله)؛ إلا كان ما أُعطِيَ أفضلَ مِمَّا أَخَذَ».' WHERE id = 1822;
UPDATE contents SET body = 'أمر الله تعالى بتكبيره، فقال: ﴿وَرَبَّكَ فَكَبِّرۡ﴾ [المدثر: ٣]، وقال ﷿: ﴿وَكَبِّرۡهُ تَكۡبِيرَۢا﴾ [الإسراء: ١١١]، وقال سبحانه: ﴿وَلَهُ ٱلۡكِبۡرِيَآءُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ﴾ [الجاثية: ٣٧].', source = 'النوع الثامن: وِرْدُ التكبير. (ص331)

حاشية: قال الشنقيطي ﵀: «أي عظمه تعظيمًا شديدًا، ويظهر تعظيم الله في شدة المحافظة على امتثال أمره، واجتناب نهيه، والمسارعة إلى كل ما يرضيه».اهـ. من «أضواء البيان» (٣/ ٦٣٥)، والدين كله في الحقيقة هو تفصيل لكلمة «الله أكبر»، فمِن ثَمَّ قال أمير المؤمنين عمر ﵁: «قول العبد: (الله أكبر)، خيرٌ من الدنيا وما فيها» كما في «تفسير القرطبي» (١٠/ ٢٢٣).' WHERE id = 1837;
UPDATE contents SET body = 'قال الحافظُ ابنُ حجرٍ ﵀: «التكبيرُ ذكرٌ مأثورٌ عندَ كلِّ أمرٍ مَهُولٍ، وعندَ كُلِّ حادِثِ سرورٍ، شكرًا لله تعالى، وتبرئةً له مِن كل ما نَسَبَ إليه أعداؤه».' WHERE id = 1838;
UPDATE contents SET body = 'وقد شُرِعَ هذا الذكرُ العظيم إما قبل الشروع في عبادة أو بعدَها، أو في المواضع الكبار التي يجتمع فيها الناسُ، أو في حضور عدوٍّ من شياطين الجن أو الإنس، أو عند رؤية آية من آيات الله ﷿.' WHERE id = 1839;
UPDATE contents SET body = 'وعن سر التكبير في هذه المواطن يقول شيخ الإسلام ابن تيمية ﵀ بعد أن ساق بعض هذه المواضع: «... وهذا كله يبين أن التكبير مشروع في المواضع الكبار لكثرة الجَمْعِ، أو لعظمة الفعل، أو لقوة الحال، أو نحو ذلك من الأمور الكبيرة، ليبين أن الله أكبر، وتستولي كبرياؤه في القلوب على كبرياء تلك الأمور الكبار؛ فيكون الدين كله لله، ويكون العبادُ له مُكَبِّرين، فيحصل لهم مقصودان: مقصود العبادة بتكبير قلوبهم لله، ومقصود الاستعانة بانقياد المطالب لكبريائه، ولهذا شُرِع التكبير على الهداية والرزق والنصر؛ لأن هذه الثلاث أكبر ما يطلبه العبد، وهي جماع مصالحه، والهدى أعظم من الرزق والنصر، لأن الرزق والنصر قد لا يُنتَفَع بهما إلا في الدنيا، وأما الهدى فمنفعته في الآخرة قطعًا».' WHERE id = 1840;
UPDATE contents SET body = 'فكل شيء له قَدْرٌ من التعظيم في نفوس العباد؛ كان دون الذي هو مُتَّصِفٌ به ﷿، والله أكبر منه، «كما أنه سبحانه فوق ما يُثني عليه العباد، كما قال أعلم الناس به ﷺ: «لا أُحصِي ثَنَاءً عليك أنتَ كَمَا أثنيتَ على نَفسِك».' WHERE id = 1849;
UPDATE contents SET body = 'وكبرياء الله ﷿ وعظمته وجلاله وكماله وسائر صفاته يستحيل أن تحيط بها العقول، أو تدركها الأفهام، وإذا كانت العقول عاجزة عن إدراك كثير من مخلوقات الله تعالى العظيمة؛ فكيف يمكن أن تدرك عظمة الرب ﷾، قال الله ﷿: ﴿وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ﴾ [البقرة: ٢٥٥].' WHERE id = 1852;
UPDATE contents SET body = 'وعن أبي ذر ﵁ قال: سمعت رسول الله ﷺ يقول: «ما الكرسيُّ في العرشِ إلَّا كَحَلْقَةٍ مِنْ حَديدٍ أُلقِيَتْ بين ظَهْرَيْ فَلاةٍ من الأرض».' WHERE id = 1853;
UPDATE contents SET body = 'وعن جابر بن عبد الله ﵄ أن رسول الله ﷺ قال: «أُذِنَ لي أن أُحَدِّثَ عن مَلَكٍ من ملائكةِ اللهِ تعالى مِن حَمَلَةِ العرش؛ إنَّ ما بين شَحمةِ أُذُنِهِ إلى عاتقه مسيرة سَبْعِ مِئَةِ عام».' WHERE id = 1854;
UPDATE contents SET body = 'وعن عبد الله بن سلام ﵁ قال رسولُ الله ﷺ: «لا تَفَكَّروا في الله، تَفَكَّروا فيما خَلَقَ اللهُ».', source = 'معنى التكبير. (ص336)

حاشية: والتفكر المأمور به في خلق الله يمرُّ بثلاث مراحل:
الأولى: أن يستحضرَ المؤمن في قلبه كِبَرَ هذه المخلوقات وعظمتها.
الثانية: أن يستحضرَ عجزَه عن إدراكها والإحاطة بها.
فيتولَّد منهما:
الثالثة: وهي معرفة الخالق ﷾ وكبرياءه، وعجز الخلق عن إدراكِ صفاته ونعوت كماله وجلاله وجماله، وهنا يرفع عقيرته مناجيًا ربَّه ومفوِّضًا إليه: «لا أُحصي ثناءً عليك، أنت كما أثنيت على نفسك».' WHERE id = 1855;
UPDATE contents SET body = 'وعن سالم بن عبد الله بن عمر عن أبيه ﵁ قال: قال رسول الله ﷺ: «تَفَكَّرُوا في آلاءِ الله، ولا تَفَكَّروا في الله».' WHERE id = 1856;
UPDATE contents SET body = 'وعن أبي هريرةَ ﵁ أنَّ رسولَ الله ﷺ قال: «قال الله تعالى: أعددتُ لعبادي الصالحين ما لا عينٌ رأَت، ولا أذن سَمِعَت، ولا خَطَرَ على قلبِ بشر». قال أبو هريرة ﵁: فاقرؤوا إن شئتم: ﴿فَلَا تَعۡلَمُ نَفۡسٞ مَّآ أُخۡفِيَ لَهُم مِّن قُرَّةِ أَعۡيُنٖ جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ﴾ [السجدة: ١٧]».' WHERE id = 1857;
UPDATE contents SET body = 'فإذا كان نعيمُ أهلِ الجنة -وهي مِن خَلْقِ الله- يعجزُ العقلُ والحواسُّ عن إدراكِهِ مهما حاولَ تخيُّلَه، فما بالُكَ بعظمةِ الخالقِ ﷿؟' WHERE id = 1858;
UPDATE contents SET body = 'وقال شيخ الإسلام ابن تيمية ﵀: «فلفظ الحول يتناول كل تحول من حال إلى حال. والقوة هي القدرة على ذلك التحوُّل، فدلَّت هذه الكلمة العظيمة على أنه ليس للعالم العلوي والسفلي حركةٌ وتحول من حال إلى حال ولا قدرة على ذلك إلا بالله، ومن الناس من يفسر ذلك بمعنًى خاصٍّ فيقول: لا حول من معصيته إلا بعصمته، ولا قوة على طاعته إلا بمعونته، والصوابُ الذي عليه الجمهور هو التفسير الأول، وهو الذي يدل عليه اللفظ.
فإن الحول لا يختص بالحول عن المعصية، وكذلك القوة لا تختص بالقوة على الطاعة، بل لفظ الحول يَعُمُّ كلَّ تحولٍ».' WHERE id = 1867;
UPDATE contents SET body = 'أن العباسَ بنَ عبدِ المُطَّلِب ﵁، قال: قلتُ: يا رسولَ الله، عَلِّمني شيئًا أسأله اللهَ ﷿، قال: «سَلِ اللهَ العافيةَ»، فمكثتُ أيامًا، ثمَّ جِئتُ، فقلتُ: يا رسولَ اللهِ، علمني شيئًا أَسألُه اللهَ، فقال لي: «يا عبَّاسُ، يا عَمَّ رسولِ الله، سَلِ اللهَ العافيةَ، في الدُّنيا والآخرة».' WHERE id = 1879;
UPDATE contents SET body = 'وعن ابن عباس ﵄ أن النبي ﷺ قال لعَمِّه العباس ﵁: «يا عَمِّ: أَكْثِرِ الدعاءَ بالعافية».' WHERE id = 1880;
UPDATE contents SET body = 'قال الإمام الكبير محمد بن محمد بن علي بن يوسف الجزري (ت: ٨٣٣ هـ) ﵀ في خاتمة كتابه «عُدَّة الحصن الحصين من كلام سيد المرسلين ﷺ» مُعَلِّقًا على الحديثين الآنِفَي الذكر: «فَلْيَنْظُرِ العاقلُ مِقْدَارَ هذه الكلمة التي اختارها رسولُ الله ﷺ لعمِّه مِن دون الكَلِم، وَلْيُؤْمِنْ بأنه ﷺ أُعْطِيَ جوامعَ الكلم، واختُصِرَتْ له الحِكَمُ، فإنَّ مَن أُعطِي العافيةَ فاز بما يرجوه ويحبه قلبًا وقالَبًا ودينًا، وَوُقِيَ ما يخافه في الدارين علمًا يقينًا، فلقد تواتر عنه ﷺ دعاؤه بالعافية، وورد عنه ﷺ لفظًا ومعنًى من نحو خمسين طريقًا. هذا وقد غُفر له ما تقدم من ذنبه وما تأخر، وهو المعصومُ على الإطلاق حقيقةً، فكيف بنا ونحن غَرَضٌ لسهام القَدَرِ وغَرَضٌ بين النَّفْسِ والشيطان والهوى، كما وَرَدَ في الخبر: (اللَّهُمَّ إنا نَسْأَلُكَ العَافِيَةَ في الدُّنْيَا وَالآخِرَةِ)».اهـ.' WHERE id = 1881;
UPDATE contents SET body = 'وقال الإمام الشوكاني ﵀: «وقد كان رسول الله ﷺ يُنزِلُ عمَّه العباسَ منزلةَ أبيه، ويرى له من الحقِّ ما يراه الولدُ لوالده، ففي تخصيصه بهذا الدعاءِ وقَصْرِه على مجرد الدعاء بالعافية تحريكٌ لِهِمَمِ الراغبين على ملازمته، وأن يجعلوه من أعظم ما يَتوسلون به إلى ربهم ﷾، ويستدفعون به كل ما يُهِمُّهم، ثم كلَّمه ﷺ بقوله: «سَلِ اللهَ العافيةَ في الدنيا والآخرة»، فكان هذا الدعاء من هذه الحيثية قد صار عُدَّةً لدفع كلِّ ضُرٍّ وجَلْبِ كلِّ خيرٍ. اللهم إنا نسألك العافيةَ في الدنيا والآخرة يا أرحمَ الراحمين آمين».' WHERE id = 1882;
UPDATE contents SET body = 'وعن أنس ﵁ قال: أتى النبيَّ ﷺ رجلٌ، فقال: يا رسولَ الله، أيُّ الدعاء أفضل؟ قال: «سَلِ اللهَ العفوَ والعافيةَ في الدنيا والآخرة».
ثم أتاه الغد فقال: يا نبيَّ الله! أيُّ الدعاء أفضل؟ قال: «سَلِ اللهَ العفوَ والعافيةَ في الدنيا والآخرة، فإذا أُعطِيتَ العافيةَ في الدنيا والآخرة؛ فقد أفلحتَ».' WHERE id = 1883;
UPDATE contents SET body = 'قال الإمام الشوكاني ﵀: «ففي هذا الحديث التصريحُ بأن الدعاء بالعافية أفضل الدعاء، ولا سيَّما بعد تكريره للسائل في ثلاثة أيام حين يأتيه للسؤال عن أفضل الدعاء، فأفاد هذا أن الدعاء بالعافية أفضل من غيره من الأدعية، مع ما قدمنا من اشتماله على جَلْبِ كُلِّ نفعٍ، ودفعِ كُلِّ ضُرٍّ، ثُمَّ في قوله في آخر هذا الحديث: «فإذا أُعْطِيتَ العافيةَ في الدنيا، وأُعْطِيتَها في الآخرة؛ فقد أفلحت» دليلٌ ظاهر واضح بأن الدعاء بالعافية يشمل أمورَ الدنيا والآخرة؛ لأنه قال هذه المقالة بعد أن قال له: «سَل ربك العافية» ثلاث مرات، فكان ذلك كالبيان لعموم بركة هذه الدعوة بالعافية لمصالح الدنيا والآخرة، ثم رتَّب على ذلك الفلاح الذي هو المقصد الأسنى والمطلوب الأكبر».اهـ.' WHERE id = 1884;
UPDATE contents SET body = 'وعن أبي هريرة ﵁ قال: سَمِعْتُ أَبَا بَكْرٍ -رِضْوانُ اللهِ عَلَيْهِ- عَلَى هذا المنبرِ يقُولُ: سَمِعْتُ رَسُولَ اللهِ ﷺ هَذَا الْيَوْمَ عَامَ أَوَّلَ يقول، ثُمَّ اسْتَعْبَرَ أَبو بَكْرٍ -رِضْوانُ اللهِ عَلَيْهِ- فَبَكَى، ثُمَّ قَالَ: سَمِعْتُ رَسُولَ الله ﷺ يَقُولُ: «لَن تُؤْتَوا شَيئًا بَعدَ كَلِمَةِ الإِخْلَاصِ مِثْلَ العَافِيَةِ، فَسَلُوا اللهَ العافيةَ».' WHERE id = 1885;
UPDATE contents SET body = 'وعن أبي بكر الصديق ﵁ أن رسول الله ﷺ قَالَ: «سَلُوا اللهَ العفوَ والعافيةَ؛ فإنَّ أحدًا لم يُعْطَ بعد اليقين خيرًا مِنَ العافية».' WHERE id = 1886;
UPDATE contents SET body = 'وعن أبي هريرة ﵁ قال: قال رسول الله ﷺ: «مَا مِن دَعْوَةٍ يَدْعُو بها العبدُ أَفْضَلُ مِن: اللَّهُمَّ إِنِّي أسألُكَ المُعافاةَ في الدُّنيا والآخرة».' WHERE id = 1887;
UPDATE contents SET body = 'وَرُوِيَ عن ابنِ عُمَرَ ﵄ قال: قال رسولُ الله ﷺ: «مَنْ فُتِحَ لَه مِنْكُم بَابُ الدُّعَاءِ؛ فُتِحَتْ له أبوابُ الرَّحْمَةِ، وما سُئِلَ اللهُ شَيْئًا: أَحَبَّ إِلَيهِ مِنْ أَنْ يُسْأَلَ العافيةَ» الحديثَ.' WHERE id = 1888;
UPDATE contents SET body = 'قال منصورٌ الفقيهُ ﵀:
رأيتُ البلاءَ كقَطْرِ السماءِ
وما تُنْبِتُ الأَرْضُ مِن نامِيَهْ
فلا تسألَنَّ إذا ما سَأَلْتَ
إلهَكَ شيئًا سِوى العافيهْ' WHERE id = 1889;
UPDATE contents SET source = 'وِرْدُ الدُّعاءِ بالعافية. (ص352)

حاشية: قيل لأنس بن مالك ﵁: إن إخوانك أَتَوْكَ من البصرة -وهو يومئذ بـ(الزاوية)- لتدعوَ الله لهم، قال: «اللهم اغفر لنا وارحمنا، وآتنا في الدنيا حسنة، وفي الآخرة حسنة، وقنا عذاب النار»، فاستزادوه، فقال مثلَها، فقال: «إن أُوتِيتُم هذا، فقد أُوتيتم خيرَ الدنيا والآخرة».' WHERE id = 1903;
UPDATE contents SET body = 'روى البخاري بسنده إلى ابن عباس ﵄ قال: ﴿ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ ﴾ [آل عمران: ١٧٣] قالها إبراهيمُ عليه السلام حين أُلقي في النار، وقالها محمدٌ ﷺ حين قالوا: ﴿ إِنَّ ٱلنَّاسَ قَدۡ جَمَعُواْ لَكُمۡ فَٱخۡشَوۡهُمۡ فَزَادَهُمۡ إِيمَٰنٗا وَقَالُواْ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ ﴾ [آل عمران: ١٧٣].' WHERE id = 1906;
UPDATE contents SET body = 'وعنه ﵁ قال: «كان آخِرَ قولِ إبراهيمَ حِينَ أُلْقِيَ في النَّارِ: حَسْبِيَ اللهُ وَنِعْمَ الْوَكِيلُ».' WHERE id = 1907;
UPDATE contents SET body = 'وعن أبي الدرداء ﵁ قال: «من قال إذا أصبح، وإذا أمسى: ﴿ حَسۡبِيَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ ﴾ [التوبة: ١٢٩] سبعَ مراتٍ؛ كفاه اللهُ ما أَهَمَّه».' WHERE id = 1908;
UPDATE contents SET body = 'وقوله تعالى: ﴿ وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَهُوَ حَسۡبُهُۥٓ ﴾ [الطلاق: ٣] معناه: كافيه أمورَ دينه ودنياه، والحسيب: الكافي، والله ﷿ كافي عبادِه؛ لأنه رازقُهم وحافظهم ومُصْلِحُ شؤونهم الذي يكفي بمعونته عن غيره، ويُستغنَى به عَمَّن سواه، قال تعالى: ﴿ أَلَيۡسَ ٱللَّهُ بِكَافٍ عَبۡدَهُۥۖ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦ ﴾ [الزمر: ٣٦]، وقال تعالى: ﴿ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٌ ﴾ [هود: ١٢]، والوكيل: الكافي الكفيل، وهو عامٌّ وخاصٌّ؛ أَمَّا العامُّ: فهو المتكَفِّلُ بأرزاقِ جميع المخلوقات وأقواتها، القائم بتدبير شؤون الكائنات وتصريف أمورها. وأَمَّا الخاصُّ بعباده المؤمنين به المتوكلين عليه، ففي قوله تعالى: ﴿ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا ﴾ [النساء: ٨١]، أي: نِعْمَ الكافي لِمَنِ التجأَ إليه، والحافظ لِمَنِ اعتصمَ به، وهو المراد في قول المؤمنين: ﴿ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ ﴾ [آل عمران: ١٧٣].' WHERE id = 1912;
UPDATE contents SET body = 'قال العلامة الطاهر بن عاشور ﵀: «في الآية الكريمة إيماءٌ إلى أنَّ الدعاءَ للوالدَيْنِ مُستَجاب؛ لأن الله أَذِنَ فيه».' WHERE id = 1927;
UPDATE contents SET body = 'وعن أبي هريرة ﵁، أن رسول الله ﷺ قال: «إذا مات الإنسانُ انقطع عملُه إلا من ثلاثٍ: صدقةٍ جاريةٍ، أو علمٍ يُنْتَفَعُ به، أو ولدٍ صالحٍ يدعو له».', source = 'النوع الثاني عشر: وِرْدُ الدعاء للوالدين في حياتهما وبعدَ موتهما. (ص359)

حاشية: أي: المؤمن؛ لحديث عمرو بن العاص ﵁ وفيه: «أما أبوك فلو كان أقرَّ بالتوحيد فصُمتَ وتصدقت عنه نفعه ذلك».' WHERE id = 1928;
UPDATE contents SET body = 'وعن أبي هريرة ﵁، قال رسول الله ﷺ: «تُرفَع للميتِ بعدَ مَوتِهِ درجةٌ، فيقول: أَيْ رَبِّ، أيُّ شيءٍ هذه؟ فيُقال: ولدُكَ استَغْفَرَ لَكَ». أو «باستغفارِ ولدِكَ لك»، وفي رواية: «بدعاءِ وَلَدِكَ لكْ».' WHERE id = 1929;
UPDATE contents SET body = 'وكان عروة بن الزبير يقول في صلاته -وهو ساجد-: «اللهم اغفر للزبير بن العوام، وأسماءَ بنتِ أبي بكر» يعني: والديه ﵄.' WHERE id = 1932;
UPDATE contents SET body = 'وكان الإمام أبو حنيفة ﵀ بَرًّا بوالديه، وكان يدعو لهما، ويستغفر لهما مع شيخه حماد، وكان يتصدق كل شهر بعشرين دينارًا عن والديه.' WHERE id = 1933;
UPDATE contents SET body = 'وأفضل صيغة للدعاء للوالدين ما جاء في كلام الملك ﷿ الذي هو مَلِكُ الكلام؛ كأن يقول:' WHERE id = 1937;
UPDATE contents SET body = 'وعن عبد الله بن عمرو ﵄ قال رسول الله صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمَ: «إنه لم يكن نبيٌّ قبلي إلا كان حقًّا عليه أن يَدُلَّ أمتَه على خيرِ ما يعلمُه لهم، وينذرَهم شَرَّ ما يعلمُه لهم».' WHERE id = 1944;
UPDATE contents SET body = 'والله ﷾ وحده هو المَعاذ والمستعاذ به، قال تعالى: ﴿ إِنَّ ٱللَّهَ يُدَٰفِعُ عَنِ ٱلَّذِينَ ءَامَنُوٓاْ ﴾ [الحج: ٣٨]، وفي قراءة: ﴿ يَدۡفَعُ ﴾، وقال سبحانه: ﴿ أَلَيۡسَ ٱللَّهُ بِكَافٍ عَبۡدَهُۥ ﴾ [الزمر: ٣٦]، وفي قراءة: ﴿ عِبادَهُ ﴾.' WHERE id = 1950;
UPDATE contents SET body = 'وقد كثر في القرآن الكريم تعوُّذُ الأنبياءِ والصالحينَ بالله ﷿؛ ومن ذلك:' WHERE id = 1952;
UPDATE contents SET body = 'وعن ابنِ عبَّاسٍ ﵄ قال: كان النبيُّ ﷺ يُعَوِّذُ الحسنَ والحسينَ ويقول: «إنَّ أباكما إبراهيمَ كان يُعَوِّذُ بها إسماعيلَ وإسحاقَ: أُعِيذُكُما بكلماتِ الله التَّامَّةِ من كلِّ شيطانٍ وهامَّةٍ، ومن كُلِّ عينٍ لامَّةٍ».' WHERE id = 1959;
UPDATE contents SET body = 'قال الإمام المحقق ابن قَيِّمِ الجوزيَّةِ ﵀: «الشَّرُّ يُقَالُ على شيئين: على الألم، وعلى ما يُفضي إليه. وليس له مسمًّى سوى ذلك، فالشرور: هي الآلام وأسبابها. فالمعاصي والكفر والشرك وأنواع الظلم هي شرور، وإن كان لصاحبها فيها نوعُ غرضٍ ولذَّةٍ، لكنها شرور؛ لأنها أسبابٌ للآلام، ومُفْضِيَةٌ إليها، كإفضاء سائر الأسباب إلى مُسَبَّباتِها، فترتُّب الألم عليها كترتب الموت على تناول السموم القاتلة، وعلى الذبح، والإحراقِ بالنار، والخنق بالحبل، وغيرِ ذلك من الأسباب التي تكون مفضية إلى مسبباتها، ولا بُدَّ، ما لم يمنع من السببية مانع، أو يعارض السببَ ما هو أقوى منه وأشدُّ اقتضاءً لضده، كما يعارض سببَ المعاصي قوةُ الإيمان، وعِظَمُ الحسناتِ الماحية وكثرتُها، فيزيد في كميتها أو كيفيتها على أسباب العذاب فيدفع الأقوى الأضعفَ».' WHERE id = 1961;
UPDATE contents SET body = 'عن ابن عابسٍ الجُهَني -وهو عقبة بن عامر- ﵁ أنَّ رسولَ الله ﷺ قال له: «يا بن عابسٍ، ألا أدُلُّكَ؟» أو قال: «ألا أخبركَ بأفضَلِ ما يتعوَّذُ به المتعوِّذون؟»، قال: بلى يا رسول الله، قال: «﴿ قُلۡ أَعُوذُ بِرَبِّ ٱلۡفَلَقِ ﴾، ﴿ قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ ﴾ هاتين السورتين»، وقال له النبيُّ ﷺ: «ما سألَ سائلٌ بمثلهِما، ولا استعاذَ مُستعيذٌ بمثلهِما».' WHERE id = 1977;
UPDATE contents SET body = 'وعن أبي سعيدٍ الخدري ﵁ قال: «كان رسولُ الله ﷺ يتعوَّذُ من عين الجانِّ وعينِ الإنسِ، فلمَّا نزلَتِ المُعوِّذتان أخذ بهما، وتَرَكَ ما سوى ذلك».' WHERE id = 1978;
UPDATE contents SET body = 'ثبت الأمر به في حديث أبي هريرة ﵁ أن النبي ﷺ قال: «إذا فرغ أحدُكم من التشهد فليتعوَّذْ بالله من أربعٍ: من عذابِ جهنمَ، ومن عذابِ القبرِ، ومن فتنةِ المَحْيا والمَماتِ، ومن شَرِّ فتنةِ المسيحِ الدجال».' WHERE id = 1981;
